from base_sensor import BaseVirtualSensor

class MPU6050_Simulator(BaseVirtualSensor):
    REG_WIDTH = 8  # MPU6050 registers are 8-bit wide

    def __init__(self):
        super().__init__()
        # Initialize all registers with their reset values
        self.regs = {
            0x19: 0x00,  # SMPLRT_DIV
            0x1A: 0x00,  # CONFIG
            0x1B: 0x00,  # GYRO_CONFIG
            0x1C: 0x00,  # ACCEL_CONFIG
            0x3B: 0x00,  # ACCEL_XOUT_H
            0x3C: 0x00,  # ACCEL_XOUT_L
            0x3D: 0x00,  # ACCEL_YOUT_H
            0x3E: 0x00,  # ACCEL_YOUT_L
            0x3F: 0x00,  # ACCEL_ZOUT_H
            0x40: 0x00,  # ACCEL_ZOUT_L
            0x6B: 0x40,  # PWR_MGMT_1
            0x75: 0x68   # WHO_AM_I
        }

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: {addr:#04x}")

        value = self.regs[addr]
        if nbytes == 1:
            return (value >> 8) & 0xFF  # Return only the high byte
        elif nbytes == 2:
            return value
        else:
            raise ValueError("Unsupported nbytes value for read_register")

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: {addr:#04x}")

        if addr == 0x6B and (data & 0x80) != 0:
            # DEVICE_RESET bit is set, reset all registers
            for reg_addr in self.regs:
                self.regs[reg_addr] = self.regs[reg_addr] & 0x7F  # Clear DEVICE_RESET bit
            return

        if addr == 0x75:
            # WHO_AM_I is read-only
            return

        if nbytes == 1:
            # Update only the high byte
            current_value = self.regs[addr]
            self.regs[addr] = (current_value & 0x00FF) | ((data << 8) & 0xFF00)
        elif nbytes == 2:
            self.regs[addr] = data
        else:
            raise ValueError("Unsupported nbytes value for write_register")

